extern "C" unsigned int strlen(const char*);

struct string_buf
{
  unsigned long long* data;
  int ref_count;
  int char_length;
  int block_length;
  int max_blocks;
};

class stringx
{
public:
  string_buf* my_buf;
  stringx();
  stringx(const stringx&);
  stringx(const char*, int = -1);
  ~stringx();
  void make_room(int);
  void append(const char*, int = -1);
  void append(const stringx&);
};

inline stringx operator+(const stringx& lhs, const stringx& rhs)
{
  stringx foo;
  foo.make_room(lhs.my_buf->char_length + rhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs);
  return foo;
}

inline stringx operator+(const char* lhs, const stringx& rhs)
{
  stringx foo;
  int len = strlen(lhs);
  foo.make_room(len + rhs.my_buf->char_length);
  foo.append(lhs, len);
  foo.append(rhs);
  return foo;
}

inline stringx operator+(const stringx& lhs, const char* rhs)
{
  stringx foo;
  int len = strlen(rhs);
  foo.make_room(len + lhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs, len);
  return foo;
}

class chunk_file
{
public:
  void open(const stringx&, int);
};

bool file_finder_exists(const stringx&, const stringx&, stringx* = 0);
void error(const stringx&);

class entity_maker
{
public:
  stringx open(chunk_file&, const stringx&, const stringx&, int);
};

stringx entity_maker::open( chunk_file& fs, const stringx& filename, const stringx& extension, int io_flags )
{
  stringx fname;
  if ( file_finder_exists( filename, extension, &fname ) )
  {
    fs.open( fname, io_flags );
    return fname;
  }
  else
  {
    error( "Couldn't open \"" + filename + extension + "\"" );
    return stringx();
  }
}
